import { useEffect, useState } from 'react'
import { api } from './api'
import { AgentTiles } from './components/AgentTiles'
import { BeforeAfterViewer } from './components/BeforeAfterViewer'
import { ChecksTable } from './components/ChecksTable'
import { ClaimsList } from './components/ClaimsList'
import { CompanyCard } from './components/CompanyCard'
import { ComplianceCard } from './components/ComplianceCard'
import { DesignTabs } from './components/DesignTabs'
import { JobBar } from './components/JobBar'
import { ModelViewer } from './components/ModelViewer'
import { Onboarding } from './components/Onboarding'
import { ProjectCard } from './components/ProjectCard'
import type { ProjectId } from './projects'
import { Recommendations } from './components/Recommendations'
import { RiskTable } from './components/RiskTable'
import { useJob, type CreateJobOptions } from './job'
import { askLiveToken } from './liveToken'
import {
  loadSaved,
  matchesDemo,
  needsLiveAgents,
  saveOnboarded,
  toRobot,
  type Onboarded,
} from './onboarding/answers'
import type { OpenAnswers } from './onboarding/questions'
import type { CheckResult, ComplianceCard as Card, DesignVariant, Robot } from './types'

// ?live=1 shows a "Run live" button. The token is asked once per tab and kept in sessionStorage.
const params = new URLSearchParams(window.location.search)
const LIVE_ENABLED = params.get('live') === '1'
// ?v4=1 shows the project switcher. Hidden until the backend handles project_id.
const V4_ENABLED = params.get('v4') === '1'

/** Start a job that makes real calls ('mixed' replays what is recorded and runs the rest). */
function startWithToken(
  mode: 'live' | 'mixed',
  start: (mode: 'live' | 'mixed', opts: CreateJobOptions) => void,
  opts: CreateJobOptions,
) {
  const token = askLiveToken('Live jobs spend TinyFish credit. Enter the live token:')
  if (token) start(mode, { ...opts, liveToken: token })
}

/** What the robot panel shows before a job: the CAD worker's starter design for the project. */
function starterRobot(project: ProjectId) {
  return project === 'ar4_club'
    ? { src: '/cad/designs/starter_ar4/glb', title: 'Robot: AR4 arm, NEMA 23 J2 motor' }
    : { src: '/cad/designs/starter/glb', title: 'Robot: NEMA 23 stepper baseline' }
}

export default function App() {
  const [health, setHealth] = useState<string>('checking…')
  const [baselineCard, setBaselineCard] = useState<Card | null>(null)
  // Checks and designs stay on the pre-v3 endpoints until the coordinated shape switch.
  const [results, setResults] = useState<CheckResult[]>([])
  const [designs, setDesigns] = useState<DesignVariant[]>([])
  const { state: job, start } = useJob()
  const [project, setProject] = useState<ProjectId>('')
  const projectId = project || undefined
  // Onboarding: the demo robot gives the defaults; `saved` is what the user confirmed before
  // (onboarded: null = they skipped to the demo robot).
  const [demo, setDemo] = useState<Robot | null>(null)
  const [example, setExample] = useState<OpenAnswers | null>(null)
  const [saved, setSaved] = useState(loadSaved)
  const [view, setView] = useState<'onboarding' | 'dashboard'>(saved ? 'dashboard' : 'onboarding')
  const onboarded = saved?.onboarded ?? null

  useEffect(() => {
    api.health().then((h) => setHealth(h.status), () => setHealth('backend unreachable'))
    api.robot().then(setDemo, console.error)
    api.example().then(setExample, console.error)
    api.compliance().then(setBaselineCard, console.error)
    api.designs().then(setDesigns, console.error)
    api
      .seedCandidates()
      .then((cs) => Promise.all(cs.map(api.checks)))
      .then(setResults, console.error)
  }, [])

  const jobOptions = (o: Onboarded | null): CreateJobOptions => ({
    projectId,
    robot: o && demo && !projectId ? toRobot(o, demo) : undefined,
  })
  /** Replay when the recordings fit this robot; otherwise a mixed job, which needs the token. */
  const run = (o: Onboarded | null) => {
    if (o && !projectId && needsLiveAgents(o.specs)) startWithToken('mixed', start, jobOptions(o))
    else start('replay', jobOptions(o))
  }
  const finishOnboarding = (o: Onboarded | null) => {
    saveOnboarded(o)
    setSaved({ onboarded: o })
    setView('dashboard')
    if (o) run(o)
  }

  if (view === 'onboarding') {
    return (
      <main className="ob-page">
        {demo ? (
          <Onboarding
            demo={demo}
            example={example}
            initial={onboarded}
            onDone={finishOnboarding}
            onSkip={() => finishOnboarding(null)}
          />
        ) : (
          <p className="muted">
            {health === 'backend unreachable' ? 'The backend is unreachable, so the questions cannot load.' : 'Loading…'}
          </p>
        )}
      </main>
    )
  }

  const runs = job.runOrder.map((id) => job.runs[id])
  // These panels come from endpoints that always use the demo robot, so they are only right
  // when the user's robot gives the same numbers.
  const demoPanels = !onboarded || (demo != null && matchesDemo(onboarded, demo))
  const card = job.compliance ?? (demoPanels ? baselineCard : null)

  return (
    <main>
      <header>
        <h1>AI Robot Redesign Engine</h1>
        <span className="muted">
          API: {health} ·{' '}
          <button type="button" className="ob-link" onClick={() => setView('onboarding')}>
            {onboarded ? 'Edit answers' : 'Describe your robot'}
          </button>
        </span>
      </header>
      <JobBar
        state={job}
        onStart={() => run(onboarded)}
        onStartLive={LIVE_ENABLED ? () => startWithToken('live', start, jobOptions(onboarded)) : undefined}
        project={project}
        onProjectChange={V4_ENABLED ? setProject : undefined}
      />
      {onboarded && !job.project && <CompanyCard company={onboarded.company} />}
      {job.project && <ProjectCard project={job.project} criteria={job.criteria} claims={job.claims} />}
      {job.riskLines.length > 0 && <RiskTable rows={job.riskLines} alternatives={job.alternatives} />}
      {job.recommendations.length > 0 && (
        <Recommendations
          recommendations={job.recommendations}
          rows={job.riskLines}
          alternatives={job.alternatives}
        />
      )}
      {job.baseline && job.candidates[0] ? (
        <BeforeAfterViewer before={job.baseline} after={job.candidates[0]} />
      ) : (
        <ModelViewer {...starterRobot(project)} />
      )}
      <div className="grid">
        {(card || demoPanels) && <ComplianceCard card={card} />}
        <AgentTiles runs={runs} />
      </div>
      <ClaimsList claims={job.claims} />
      {demoPanels && <ChecksTable results={results} />}
      {demoPanels && <DesignTabs designs={designs} />}
      <footer className="muted">
        Not legal advice. Pass* = passes the checks we implemented, not engineering certification.
      </footer>
    </main>
  )
}
// Job view state. The UI is a pure function of the event log: `applyEvent` folds one event
// into the state, and `useJob` feeds it from the SSE stream.

import { useCallback, useEffect, useReducer, useRef } from 'react'
import type {
  Alternative,
  BomLine,
  Claim,
  Criteria,
  Design,
  JobEvent,
  JobMode,
  JobStatus,
  Level,
  LineRisk,
  Outcome,
  Project,
  Recommendation,
  Stage,
} from './events'
import { TERMINAL_STAGES } from './events'
import type { ComplianceCard, Robot } from './types'

const BASE = import.meta.env.VITE_API_URL ?? ''

export interface Run {
  runId: string
  worker: string
  site: string
  url: string | null
  /** False for a replayed run: its streaming URL points at a browser that no longer exists. */
  live: boolean
  streamingUrl: string | null
  steps: string[]
  outcome: Outcome | null
  reason: string | null
}

export interface ClaimRow {
  claim: Claim
  verified: boolean
  reason: string | null
}

export interface JobState {
  jobId: string | null
  mode: JobMode | null
  stage: Stage | null
  lastEventId: number
  runs: Record<string, Run>
  runOrder: string[]
  claims: ClaimRow[]
  compliance: ComplianceCard | null
  /** The robot before the swap, and each redesigned candidate (one per tournament entry). */
  baseline: Design | null
  candidates: Design[]
  errors: string[]
  connection: 'idle' | 'starting' | 'streaming' | 'closed' | 'failed'
  // v4 supply-risk view; empty for the wheeled demo job.
  project: Project | null
  criteria: Criteria | null
  /** One entry per BOM line, in arrival order; a later risk_line for the same line replaces it. */
  riskLines: RiskRow[]
  alternatives: Record<string, Alternative[]>
  /** Ranked: risk levels dropped (desc), then cost delta (asc). */
  recommendations: Recommendation[]
}

export interface RiskRow {
  line: BomLine
  risk: LineRisk
}

export const initialJobState: JobState = {
  jobId: null,
  mode: null,
  stage: null,
  lastEventId: 0,
  runs: {},
  runOrder: [],
      unpriced++
      continue
    }
    const cost = l.unit_price_usd * l.qty
    total += cost
    const tier = l.origin_tier
    if (l.origin_country?.toUpperCase() === 'US' && (tier === 'T1' || tier === 'T2')) domestic += cost
  }
  return total > 0 ? { pct: Math.round((domestic / total) * 1000) / 10, unpriced } : null
}

export function isTerminal(state: JobState): boolean {
  return state.stage !== null && TERMINAL_STAGES.has(state.stage)
}

function updateRun(state: JobState, runId: string, patch: Partial<Run>): JobState {
  const run = state.runs[runId]
  if (!run) return state // event for a run we never saw start; ignore rather than invent one
  return { ...state, runs: { ...state.runs, [runId]: { ...run, ...patch } } }
}

/** Fold one event into the state. Events at or below lastEventId are duplicates from a resume. */
export function applyEvent(prev: JobState, ev: JobEvent): JobState {
  if (ev.id <= prev.lastEventId) return prev
  const state = { ...prev, lastEventId: ev.id }

  switch (ev.type) {
    case 'stage':
      return { ...state, stage: ev.data.stage }
    case 'run_started': {
      const d = ev.data
      const run: Run = {
        runId: d.run_id,
        worker: d.worker,
        site: d.site,
        url: d.url,
        live: d.live,
        streamingUrl: null,
        steps: [],
        outcome: null,
        reason: null,
      }
      return {
        ...state,
        runs: { ...state.runs, [d.run_id]: run },
        runOrder: state.runOrder.includes(d.run_id) ? state.runOrder : [...state.runOrder, d.run_id],
      }
    }
    case 'run_streaming_url':
      return updateRun(state, ev.data.run_id, { streamingUrl: ev.data.streaming_url })
    case 'run_progress': {
      const run = state.runs[ev.data.run_id]
      return run ? updateRun(state, run.runId, { steps: [...run.steps, ev.data.purpose] }) : state
    }
    case 'run_finished':
      return updateRun(state, ev.data.run_id, {
        outcome: ev.data.outcome,
        reason: ev.data.reason,
        live: ev.data.live,
      })
    case 'claim_verified':
      return { ...state, claims: [...state.claims, { claim: ev.data.claim, verified: true, reason: null }] }
    case 'claim_rejected':
      return {
        ...state,
        claims: [...state.claims, { claim: ev.data.claim, verified: false, reason: ev.data.reason }],
      }
    case 'compliance':
      return { ...state, compliance: ev.data.card }
    case 'error':
      return { ...state, errors: [...state.errors, ev.data.message] }
    case 'design_ready':
      return ev.data.role === 'baseline'
        ? { ...state, baseline: ev.data }
        : { ...state, candidates: [...state.candidates, ev.data] }
    case 'project':
      return { ...state, project: ev.data.project, criteria: ev.data.criteria }
    case 'risk_line': {
      const row = { line: ev.data.line, risk: ev.data.risk }
      const i = state.riskLines.findIndex((r) => r.risk.line_id === row.risk.line_id)
      const riskLines =
        i < 0 ? [...state.riskLines, row] : state.riskLines.map((r, j) => (j === i ? row : r))
      return { ...state, riskLines }
    }
    case 'alternative': {
      const alt = ev.data.alternative
      const list = (state.alternatives[alt.line_id] ?? []).filter((a) => a.id !== alt.id)
      return { ...state, alternatives: { ...state.alternatives, [alt.line_id]: [...list, alt] } }
    }
    case 'recommendation': {
      const rec = ev.data.recommendation
      const others = state.recommendations.filter((r) => r.line_id !== rec.line_id)
      return { ...state, recommendations: rankRecommendations([...others, rec]) }
    }
    default:
      return state // check_result, advocate, synthesis: not rendered yet
  }
}

type Action =
