  /** True when a live agent found it; false for a research row. */
  live: boolean
}

export interface Recommendation {
  line_id: string
  action: 'keep' | 'dual_source' | 're_source'
  alternative_id: string | null
  cost_delta_usd: number | null
  risk_before: Level
